import{_ as t,o,c as n,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/INSERT.md","filePath":"manual-en/INSERT.md","lastUpdated":1785684581000}'),i={name:"manual-en/INSERT.md"};function s(c,e,d,r,l,h){return o(),n("div",null,[...e[0]||(e[0]=[a(`<h3 id="_17-16-insert" tabindex="-1">17.16 INSERT <a class="header-anchor" href="#_17-16-insert" aria-label="Permalink to &quot;17.16 INSERT&quot;">​</a></h3><pre><code>     INSERT [FILE=]’file_name’
        [CD={NO,YES}]
        [ERROR={CONTINUE,STOP}]
        [SYNTAX={BATCH,INTERACTIVE}]
        [ENCODING={LOCALE, ’charset_name’}].
</code></pre><p><code>INSERT</code> is similar to <code>INCLUDE</code> (see <a href="./INCLUDE">INCLUDE</a>) but somewhat more flexible. It causes the command processor to read a file as if it were embedded in the current command file.</p><p>If <code>CD=YES</code> is specified, then before including the file, the current directory becomes the directory of the included file. The default setting is ‘CD=NO’. Note that this directory remains current until it is changed explicitly (with the <code>CD</code> command, or a subsequent <code>INSERT</code> command with the ‘CD=YES’ option). It does not revert to its original setting even after the included file is finished processing.</p><p>If <code>ERROR=STOP</code> is specified, errors encountered in the inserted file causes processing to immediately cease. Otherwise processing continues at the next command. The default setting is <code>ERROR=CONTINUE</code>.</p><p>If <code>SYNTAX=INTERACTIVE</code> is specified then the syntax contained in the included file must conform to interactive syntax conventions. See <a href="./Syntax-Variants">Syntax Variants</a>. The default setting is <code>SYNTAX=BATCH</code>.</p><p><code>ENCODING</code> optionally specifies the character set used by the included file. Its argument, which is not case-sensitive, must be in one of the following forms:</p><p><code>LOCALE</code></p><p>The encoding used by the system locale, or as overridden by the <code>SET</code> command (see <a href="./SET">SET</a>). On GNU/Linux and other Unix-like systems, environment variables, <em>e.g.</em> <code>LANG</code> or <code>LC_ALL</code>, determine the system locale.</p><p>charset_name</p><p>One of the character set names listed by IANA at <a href="http://www.iana.org/assignments/character-sets" target="_blank" rel="noreferrer">http://www.iana.org/assignments/character-sets</a>. Some examples are <code>ASCII</code> (United States), <code>ISO-8859-1</code> (western Europe), <code>EUC-JP</code> (Japan), and <code>windows-1252</code> (Windows). Not all systems support all character sets.</p><p><code>Auto,encoding</code></p><p>Automatically detects whether a syntax file is encoded in an Unicode encoding such as UTF-8, UTF-16, or UTF-32. If it is not, then PSPP generally assumes that the file is encoded in encoding (an IANA character set name). However, if encoding is UTF-8, and the syntax file is not valid UTF-8, PSPP instead assumes that the file is encoded in <code>windows-1252</code>.</p><p>For best results, encoding should be an ASCII-compatible encoding (the most common locale encodings are all ASCII-compatible), because encodings that are not ASCII compatible cannot be automatically distinguished from UTF-8.</p><p><code>Auto</code><code>Auto,Locale</code></p><p>Automatic detection, as above, with the default encoding taken from the system locale or the setting on <code>SET LOCALE</code>.</p><p>When ENCODING is not specified, the default is taken from the --syntax-encoding command option, if it was specified, and otherwise it is <code>Auto</code>.</p>`,17)])])}const f=t(i,[["render",s]]);export{p as __pageData,f as default};
